import{_ as t,o,c as d,a0 as a}from"./chunks/framework.C3yZ6M33.js";const m=JSON.parse('{"title":"on: event patterns","description":"","frontmatter":{},"headers":[],"relativePath":"reference/on-grammar.md","filePath":"reference/on-grammar.md"}'),c={name:"reference/on-grammar.md"};function r(n,e,i,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="on-event-patterns" tabindex="-1"><code>on:</code> event patterns <a class="header-anchor" href="#on-event-patterns" aria-label="Permalink to &quot;`on:` event patterns&quot;">​</a></h1><p>The grammar every <code>on:</code> entry (and every glob-matched event-type position) uses. Matching lives in <code>peregrin-bus</code>; the semantics are ported 1:1 from the v1 <code>matchPattern</code>/<code>captureWildcards</code>.</p><h2 id="pattern-grammar" tabindex="-1">Pattern grammar <a class="header-anchor" href="#pattern-grammar" aria-label="Permalink to &quot;Pattern grammar&quot;">​</a></h2><p>Event types are dot-separated segments. A pattern is the same shape with two wildcard segments:</p><table tabindex="0"><thead><tr><th>Segment</th><th>Matches</th><th>Capture</th></tr></thead><tbody><tr><td>literal</td><td>itself, exactly</td><td>—</td></tr><tr><td><code>*</code></td><td>exactly one segment</td><td>one segment</td></tr><tr><td><code>**</code></td><td>zero or more segments</td><td>all matched segments, re-joined with <code>.</code></td></tr></tbody></table><p>Only a whole segment can be a wildcard — <code>fo*</code> is a literal segment, not a prefix glob.</p><p>The matcher backtracks left to right: <code>**</code> is tried from zero segments upward and the first split that lets the remainder of the pattern match wins. Match/no-match is unaffected by that order; it only decides captures for ambiguous patterns like <code>**.**</code> (the first <code>**</code> takes the minimal split).</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Matches</th><th>Does not match</th></tr></thead><tbody><tr><td><code>start</code></td><td><code>start</code></td><td><code>start.x</code></td></tr><tr><td><code>lint.*</code></td><td><code>lint.passed</code></td><td><code>lint</code>, <code>lint.a.b</code></td></tr><tr><td><code>task.**</code></td><td><code>task</code>, <code>task.x</code>, <code>task.x.y.z</code></td><td><code>taskx</code></td></tr><tr><td><code>**.done</code></td><td><code>done</code>, <code>x.done</code>, <code>x.y.done</code></td><td><code>x.passed</code></td></tr><tr><td><code>shard.*.done</code></td><td><code>shard.42.done</code></td><td><code>shard.1.2.done</code></td></tr></tbody></table><h2 id="captures" tabindex="-1">Captures <a class="header-anchor" href="#captures" aria-label="Permalink to &quot;Captures&quot;">​</a></h2><p>Each wildcard captures; captures are 1-indexed in pattern order across <code>*</code> and <code>**</code> (<code>**</code> captures join back with <code>.</code>):</p><ul><li><code>${event.match.N}</code> — the Nth wildcard&#39;s captured text.</li><li><code>${event.shard}</code> — alias for <code>match.1</code> (the shard idiom <code>shard.*.done</code> → <code>shard</code> = <code>42</code>).</li></ul><p>Captures come from the first <code>on</code> pattern that matched the trigger event — the same source <code>forward:</code> substitution uses. See <a href="./scope-resolution.html">Scope resolution</a> for the <code>${event.*}</code> forms.</p><h2 id="trigger-semantics-—-mode" tabindex="-1">Trigger semantics — <code>mode:</code> <a class="header-anchor" href="#trigger-semantics-—-mode" aria-label="Permalink to &quot;Trigger semantics — `mode:`&quot;">​</a></h2><p><code>on:</code> subscribes a node to event types; <code>mode</code> picks how the subscription fires:</p><table tabindex="0"><thead><tr><th><code>mode</code></th><th>Fires when</th><th><code>triggers</code> bound for the fire</th></tr></thead><tbody><tr><td><code>any</code> (default)</td><td>each published event matches any <code>on</code> pattern</td><td>the single matching event</td></tr><tr><td><code>all</code></td><td>every <code>on</code> pattern has ≥1 matching event in the log</td><td>first matching event per <strong>distinct</strong> pattern, in <code>on</code> order</td></tr></tbody></table><p><code>mode: all</code> is the fan-in primitive: once satisfied it fires once (duplicate identical patterns count once). With <code>max_fires</code> it can fire again — each fire needs all patterns satisfied by the log.</p><p><code>fan_in:</code> is the count-based alternative: it considers only <code>on[0]</code> and fires when the number of logged events matching that pattern reaches <code>count</code> (or <code>count_from</code>, a <code>config</code> dotted path resolving to an array length or number; default 1). The driver is skipped and the node emits <code>fan_in.emit</code> (else <code>emits[0]</code>, else <code>&lt;id&gt;.done</code>) with payload <code>{count, triggers: [{type, source, payload}, …]}</code>.</p><h2 id="eligibility-gates" tabindex="-1">Eligibility gates <a class="header-anchor" href="#eligibility-gates" aria-label="Permalink to &quot;Eligibility gates&quot;">​</a></h2><p>Independent of <code>mode</code>, a node stops being a candidate when:</p><ul><li><strong><code>max_fires</code></strong> — fire count reaches the cap; once exhausted, a <code>node.exhausted</code> side event is emitted the next time an event matches (for <code>mode: all</code>, only once all patterns are satisfied). <code>unlimited</code> never exhausts.</li><li><strong><code>until</code></strong> — any listed type has been seen; also suppresses the <code>node.exhausted</code> side event.</li><li><strong><code>retire_on</code></strong> — any listed type has been seen; the node is removed from the live graph entirely.</li></ul><h2 id="exact-match-positions" tabindex="-1">Exact-match positions <a class="header-anchor" href="#exact-match-positions" aria-label="Permalink to &quot;Exact-match positions&quot;">​</a></h2><p>Verified against v1: <strong>only <code>on:</code> patterns glob-match</strong> (plus the <code>fan_in</code> count pattern, <code>forward</code> capture source, and the <code>output:</code> schema lookup — exact first, then wildcard). These positions compare literally and do <strong>not</strong> glob:</p><ul><li><code>until:</code> — stop-listening list</li><li><code>retire_on:</code> — retire list</li><li><code>stop_on:</code> — campaign-level run terminators</li><li><code>emits:</code> strict check — declared-type verification</li></ul><p>Keeping <code>until</code>/<code>retire_on</code>/<code>stop_on</code> exact is deliberate: lifecycle lists name concrete terminator events. The <code>emits:</code> gap is tracked as I-012 — see <a href="./event-envelope.html">Event envelope</a>.</p>',24)])])}const g=t(c,[["render",r]]);export{m as __pageData,g as default};
